#include <bits/stdc++.h>
using namespace std;

const int N = 1005;
int val[N], nxt[N];

int main() {
    int n;
    cin >> n;

    for (int i = 0; i < n; i++) {
        cin >> val[i];
        nxt[i] = i + 1;       // 默认指向下一个位置
    }
    nxt[n - 1] = -1;          // 最后一个结点后面没有结点

    for (int cur = 0; cur != -1; cur = nxt[cur]) {
        cout << val[cur] << " ";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1005;
int val[N], nxt[N];

int main() {
    int n, x;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> val[i];
        nxt[i] = i + 1;
    }
    nxt[n - 1] = -1;
    cin >> x;

    int head = 0;

    // 如果头结点就是 x，需要单独移动 head
    if (head != -1 && val[head] == x) {
        head = nxt[head];
    } else {
        int cur = head;
        while (cur != -1 && nxt[cur] != -1) {
            int nextNode = nxt[cur];
            if (val[nextNode] == x) {
                nxt[cur] = nxt[nextNode]; // 让 cur 跳过 nextNode
                break;
            }
            cur = nxt[cur];
        }
    }

    for (int cur = head; cur != -1; cur = nxt[cur]) {
        cout << val[cur] << " ";
    }
    return 0;
}
